import sys

class Banks:
    def calculateCreditScore(self):
        pass

class RBI(Banks):
    CREDIT = 0.10

    def __init__(self, accountNumber, creditScore, holderName):
        self.__accountNumber = accountNumber
        self.__creditScore = creditScore
        self.__holderName = holderName

    def calculateCreditScore(self, amount):
        return round(self.__creditScore + amount * self.CREDIT, 2)

    def display(self, bank_type, amount):
        gained = amount * self.CREDIT
        print(f"Hi, {self.__holderName} You have gained {gained:.2f} credit score for the payment of {amount}")
        print(f"Your Total Credit Score is {self.calculateCreditScore(amount):.2f}")

class ICICI(RBI):
    pass

class HDFC(RBI):
    pass

def main():
    data = sys.stdin.read().strip().split()
    if not data or len(data) < 5:
        return

    bank_type = int(data[0])
    name = data[1]
    account_number = data[2]
    prev_score = float(data[3])
    amount = float(data[4])

    if bank_type == 1:
        bank = ICICI(account_number, prev_score, name)
        bank_type_str = "ICICI"
    elif bank_type == 2:
        bank = HDFC(account_number, prev_score, name)
        bank_type_str = "HDFC"
    else:
        return

    bank.display(bank_type_str, amount)

if __name__ == "__main__":
    main()
